  },
  "criteria": {
    "definition": {
      "assessment": "partial",
      "reason": "动机、实例身份、输入输出、字节边界和采集状态充分；但没有区分事件逻辑启用时间与实际占用计数器的运行时间，给出的缩放定义不能直接用于正文覆盖的 perf 复用场景。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "启用比例为 r_k=T_enabled,k/T_obs。若事件率在这个窗内可代表整个 W，缩放估计可写成 C_hat_k=C_k(W)/r_k"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "采集状态至少包括：逻辑实例身份、pass 编号 p、事件组、启用区间、cache 策略、时钟策略、是否串行化、并发 kernel 集合、指标来源是硬件计数器还是软件插桩。"
        }
      ]
    },
    "legality": {
      "assessment": "partial",
      "reason": "范围、方向、共享资源和并发正确性边界展开充分；但把不同 pass 一律判为不能构成有意义比率，与所供 Nsight Compute 文档支持的确定性 replay 合并相冲突。需要区分直接同次观测、受条件约束的跨 pass 估计和不可合并样本。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "命中次数来自 pass 1、查询次数来自 pass 2，或 instructions 取线程范围而 cycles 取系统范围，都不能组成一个有意义的比率。"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "需要正确并发执行的 kernel 不应被强制串行化成单 kernel 观测"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "提供了问题分解、模式选择、预算、采集、校验与反证的数据流；但选择四种 replay 模式之后，执行循环没有按模式展开，后续 pass 无条件恢复写集，也没有明确 application 模式重新执行整个应用。该状态转换与正文自己的模式定义不一致。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "建立或恢复本 pass 的初始状态；p>0 时恢复上一 pass 确定的写集"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "application replay 重跑整个应用，不保存恢复 kernel 内存"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "不能同 pass 取得时，标记 unresolved 或重跑为单组事件"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "六类成本、保存量与写集恢复量、请求与 sector/wavefront 的区别及 IPC 算例均有实质内容；但 replay 加和式缺少成立为下界的串行和速率上界条件，且把来源中的相对吞吐 4/5、9/10 写成了流量放大，违反本章自己的符号定义。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "C_replay >= C_setup + P*T_exec + (S_save+(P-1)*W_written)/B_restore"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "相邻 warp 的 cache 复用还可能把看似 4/5 的放大变成 9/10"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "同一请求可以有 4 个 sector、1 个 wavefront，也可以有 4 个 sector、2 个 wavefront；后者表示流水占用更多周期。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "对 cache、时钟、并发、graph、共享单元、平台迁移、CPU 范围和短工作负载分别说明了保留关系及调整或放弃条件，没有将隔离测量直接外推为服务效果。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "默认清空 cache 的隔离结果不能代表应用热态；必须在同一 cache 策略下比较，必要时放弃隔离结论"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "CU 数、wave 宽度、VGPR/SGPR、LDS bank 和事件名都改变；不复制 CUDA 的 lane/bank 常数"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "对低带宽、高命中却慢、驻留增加却退化、local memory、IPC 和服务收益提供了竞争解释、可控干预及反证后的判断修正。其设备效果均保留为待测，符合当前证据范围；跨 pass 的错误合法性规则需按 finding 单独修正。",
      "evidence": [
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "若增加驻留仍不提高事务率，降低 occupancy 解释权重"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "查生成资源报告和 local 读写；缩短临时量寿命或改变 tile，再核对相同计算的 traffic"
        },
        {
          "path": "knowledge/tools/kernel-counter-replay.md",
          "quote": "容量或字节收益不等于带宽或延迟收益"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-TOOLS-003-LEGALITY-001",
      "criterion": "legality",
      "evidence": "正文：“命中次数来自 pass 1、查询次数来自 pass 2，或 instructions 取线程范围而 cycles 取系统范围，都不能组成一个有意义的比率。”算法：“不能同 pass 取得时，标记 unresolved 或重跑为单组事件”。所供 S-NCU §2.2.3 明确讨论将同一 launch 的多个 application replay pass 计数正确识别并合并；§2.3.4 则将跨 pass 比率误差与工作分布变化、未达稳态等条件联系起来，并未一律禁止。",
      "impact": "把 replay 的受条件约束估计误写为普遍非法，可能拒绝工具正常形成的多 pass 派生指标；某些事件无法同时采集时，建议的单组重跑也不能解决硬件限制。脚本将这一过强规则固化为负对照。",
      "blocking": true,
      "required_revision": "区分同 pass 的直接比率、经过实例匹配与状态控制且验证稳定性的跨 pass 估计，以及状态或范围不匹配的非法拼接。为跨 pass 结果保留估计标签和变化范围；若本章选择更保守地不输出，明确这是本章策略。同步修正伪代码、适配表和检查，保留对错误匹配及非平稳采集的拒绝。"
    },
    {
      "id": "K-TOOLS-003-DEFINITION-001",
      "criterion": "definition",
      "evidence": "正文：“启用比例为 r_k=T_enabled,k/T_obs”及“C_hat_k=C_k(W)/r_k”。所供 S-PERF 输出定义分别列出“run time of counter”和“percentage of measurement time the counter was running”。脚本 scaled_count 只接收预先给定的 enabled_fraction，没有核验它来自何种时间。",
      "impact": "perf 复用时逻辑上 enabled 不代表实际 running。若测量和逻辑启用均为 1 秒、事件实际运行 0.25 秒且计到 250，按当前定义 r=1 会得到 250；在代表性成立时，复用缩放应为 1000。线程未运行的时间也不能未经说明外推为事件活动。",
      "blocking": true,
      "required_revision": "分别定义墙钟窗口、逻辑 time_enabled 和实际 time_running。说明 perf 复用缩放使用 C_raw×time_enabled/time_running，并限定代表性、零运行时间及已缩放输出的处理；若通用模型用运行时间占墙钟比例，明确其不同估计目标。检查应从这些时间输入推导比例，加入 enabled 与 running 不等的例子。"
    },
    {
      "id": "K-TOOLS-003-ALGORITHM-001",
      "criterion": "algorithm",
      "evidence": "算法选择了“range 或 application-range”和“application replay”，但统一循环规定：“建立或恢复本 pass 的初始状态；p>0 时恢复上一 pass 确定的写集”。正文另称：“application replay 重跑整个应用，不保存恢复 kernel 内存”。",
      "impact": "读者无法按伪代码恢复所声明的四种模式：application/application-range 会被错误要求执行工具写集恢复，而仅执行候选实例又不能重建主机活动和应用依赖；range 的采集单位及恢复对象也不同于单 kernel 写集。",
      "blocking": true,
      "required_revision": "在执行循环中按模式明确初始化、执行对象和后续 pass 推进：kernel replay 使用首 pass 确定的写集及原始备份；application replay 重跑应用并匹配 launch；range replay 捕获和重放范围并按范围恢复必要状态；application-range 重跑应用并匹配范围。补上 range 可同步上下文、API 支持及被恢复主机地址仍有效的前提或准确委托说明，并对失败停止派生。"
    },
    {
      "id": "K-TOOLS-003-COST-001",
      "criterion": "cost",
      "evidence": "正文：“C_replay >= C_setup + P*T_exec + (S_save+(P-1)*W_written)/B_restore”，随后限定“B_restore 是保存/恢复路径的可持续速率”并说明“传输可重叠”。",
      "impact": "数量级估算采用 >= 仍然声称必要下界。当前没有证明各项全部串行，也没有证明可持续速率是传输能力上界；不同 pass 的执行时间还可能不同。该式不能在现有前提下作为预算拒绝测量的可靠下界。",
      "blocking": true,
      "required_revision": "将其明确改为串行记账模型下的近似预算，并定义模式、P、各 pass 执行时间及保存/恢复路径；或者给出足以支持下界的串行依赖和能力上界假设。允许重叠时按依赖及共享资源列必要时间。明确单 pass 保存恢复为零，application 模式另计整次应用成本。"
    },
    {
      "id": "K-TOOLS-003-COST-002",
      "criterion": "cost",
      "evidence": "正文先定义“放大 A=D_tx/D_use，效率 E=D_use/D_tx”，后称“相邻 warp 的 cache 复用还可能把看似 4/5 的放大变成 9/10”。所供 S-CUDA-BEST §9.2.1.3 的 4/5 是预期相对吞吐，9/10 是该 V100 例子中的相对吞吐观察。",
      "impact": "把相对吞吐、字节效率与事务放大混为同一量。128 字节有效访问覆盖 160 字节段时，放大为 5/4；来源中的 9/10 吞吐也不能直接当作测得的事务效率。",
      "blocking": true,
      "required_revision": "将 4/5 与 9/10 正确标为相对对齐基线的预期和观察吞吐，并与 D_tx/D_use 分开。需要说明字节放大时使用明确边界下的 160/128=5/4，不从吞吐比例直接反推实际 DRAM 字节。"
    }
  ],
  "limitations": [
    "未取得目标 GPU replay、CPU PMU、真实事务、cache 一致性、并发可见性或无 profiler 服务性能证据；正文已清楚声明这些边界，边界本身不构成拒收理由。",
    "来源事实核对限于所供固定版本文本和摘录；没有读取上游实现源码或将来源历史设备性能外推到目标设备。",
    "本次无法直接访问本地文件或运行 Python；检查执行判断依据用户提供的实际隔离 preflight 记录，没有声称独立重跑、重新计算文件哈希或通过链接存在性检查。",
    "reader.html 未提供正文，未实际打开；离线链接只核对了给出的相对路径关系及关联材料身份。"
  ],
  "checks": [
    {
      "script": "tools/check_k_tools_003_full.py",
      "args": []
    }
  ],
  "reading_scope": "已完整阅读本轮提供的全部材料。字符范围均为提取文本零基半开区间。完整文件：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/tools/kernel-counter-replay.md [0,10937)；五份来源说明 S-NCU [0,477)、S-CUDA-BEST [0,992)、S-ROCM [0,514)、S-PERF [0,503)、S-LINUX-IO [0,850)；knowledge/tools/timeline-attribution.md [0,3485)；knowledge/hardware/cpu-linear-kernels.md [0,4016)；knowledge/frameworks/cpu-quantized-kernels.md [0,3369)；knowledge/hardware/storage-io.md [0,3886)；knowledge/hardware/transport-and-rdma.md [0,4088)；knowledge/tools/gpu-characterization.md [0,5952)；references/S-ROCM/fulltext.txt [0,32330)；references/S-PERF/fulltext.txt [0,25043)；references/S-LINUX-IO/fulltext.txt [0,52366)。完整检查脚本为 candidate.test_script 从 shebang 至末尾 main() 调用；另完整审阅 author_notes 和 actual_preflight 的输出及执行元数据。仅摘录：knowledge/hardware/memory-and-roofline.md [0,3727)、[8000,12000)；knowledge/frameworks/triton-kernels.md [0,1159)、[8000,14568)；knowledge/hardware/gpu-kernel-pipelines.md [4000,7727)、[8000,12000)；knowledge/hardware/precision-and-kernel-support.md [0,368)、[8000,15359)；knowledge/hardware/cpu-serving.md [0,547)、[8000,15180)；references/S-NCU/fulltext.txt [0,28000)、[32000,40000)、[56000,64000)、[96000,100000)、[104000,124000)、[136000,139881)；references/S-CUDA-BEST/fulltext.txt [44000,75881)、[76000,80000)、[84000,104000)、[108000,112000)、[128000,132000)、[160000,164000)、[176000,180000)。摘录文件未列入 documents，未据此声称阅读全文。S-PERF 的 include 和 S-LINUX-IO 的 kernel-doc 引用未递归展开，完整阅读仅指所供文件。",
  "test_assessment": "提供的 remote_bwrap 记录绑定脚本 SHA256 05e2891f8206137d6dc194c0c6d795a7c2c319c09c3e2bdb17d4e2d58698c334，returncode=0、stderr 为空且未超时；本次审阅未重新执行。replay 测试以从原始 base 直接构造的单次输出作为参考，四次恢复结果一致，关闭恢复后出现逐 pass 累加，确实检测了标量模型中初始内存被污染的机制，并覆盖零次、一次执行。occupancy 用可行驻留数枚举对照 min 公式，检测忽略共享内存约束的 12 对 6 差异；两条路径共享寄存器取整函数，因此不能独立验证该硬件分配模型。IPC 的 2 与 4/3 使用明确整数参考，并实际拒绝跨区间输入。跨 pass、命中数超查询数、零比例和多链路输入的拒绝分支实际被触发；但跨 pass 拒绝验证的是正文中过强的策略，不能证明该策略符合 Nsight Compute replay 语义。流量恒等式由同一批输入代数构造，独立验证力有限；多边界负对照只验证边界数量拒绝。脚本没有表示完整 X、单位、工具缩放状态、time_enabled/time_running 的区别，也没有测试四种 replay 模式、应用匹配失败、range 恢复或 replay 成本公式。作者将其限定为标量模型是正确的；author_notes 所称两个 pseudocode 块与实际正文一个块不符，但块数不作为验收条件。现有退出码不能关闭上述语义缺口。"
}
